CAMPOS = [("equipo_profesores", "PROFESOR"), ("equipo_estudiantes", "ESTUDIANTE"), ("expertos_invitados", "EXPERTO")]


def texto_a_participantes(apps, schema_editor):
    """Cada linea (o elemento separado por coma) de los campos de texto libre pasa
    a ser un participante; el profesor completa cedula y correo al editar."""
    Integracion = apps.get_model("seguimiento", "IntegracionAcademica")
    Participante = apps.get_model("seguimiento", "ParticipanteIntegracion")
    for integracion in Integracion.objects.all():
        for campo, rol in CAMPOS:
            texto = getattr(integracion, campo) or ""
            nombres = [n.strip() for linea in texto.splitlines() for n in linea.split(",") if n.strip()]
            Participante.objects.bulk_create(
                Participante(integracion=integracion, rol=rol, nombre=nombre[:150]) for nombre in nombres
            )


def participantes_a_texto(apps, schema_editor):
    Integracion = apps.get_model("seguimiento", "IntegracionAcademica")
    for integracion in Integracion.objects.prefetch_related("participantes"):
        for campo, rol in CAMPOS:
            setattr(integracion, campo, "\n".join(p.nombre for p in integracion.participantes.all() if p.rol == rol))
        integracion.save(update_fields=[c for c, _ in CAMPOS])


